<template>
  <PageContainer title="AI 模型配置" description="配置智能体使用的大模型服务，密钥仅在后端加密保存">
    <template #actions><el-button :loading="loading" @click="load">刷新</el-button><el-button type="primary" @click="openEditor()">添加模型</el-button></template>
    <el-alert title="首次使用：添加模型 → 填写 API Key → 保存 → 连接测试 → 设为当前模型。没有配置时，系统仍可使用本地规则生成结构化分析。" type="info" show-icon :closable="false" class="notice"/>
	<div class="usage-metrics"><DataCard label="调用次数" :value="compactNumber(usage.requests)"/><DataCard label="成功率" :value="`${((usage.success_rate||0)*100).toFixed(1)}%`"/><DataCard label="输入 Token" :value="compactNumber(usage.prompt_tokens)" sub="发送给模型的内容"/><DataCard label="输出 Token" :value="compactNumber(usage.completion_tokens)" sub="模型生成的内容"/><DataCard label="总 Token" :value="compactNumber(usage.total_tokens)"/><DataCard label="95% 响应时间" :value="`${usage.p95_latency_ms||0} ms`" sub="大多数请求可在此时间内完成"/></div>
    <section class="data-table-card"><div class="toolbar"><strong>模型配置</strong><span class="muted">只有连接测试成功的配置才能设为当前模型</span></div><div class="table-scroll-x"><el-table :data="configs" v-loading="loading" class="model-table" empty-text="尚未添加模型配置">
      <el-table-column label="使用状态" width="110"><template #default="{row}"><el-tag :type="row.is_default?'success':'info'">{{row.is_default?'当前使用':'备用'}}</el-tag></template></el-table-column><el-table-column prop="name" label="配置名称" width="160"/><el-table-column label="服务商" width="140"><template #default="{row}">{{providerName(row.provider_code)}}</template></el-table-column><el-table-column prop="model" label="模型名称" min-width="170"/><el-table-column prop="api_key_masked" label="密钥" width="110"/><el-table-column label="连接状态" min-width="220"><template #default="{row}"><div class="test-result"><el-tag :type="testTag(row.last_test_status)">{{testStatus(row.last_test_status)}}</el-tag><small v-if="row.last_test_message">{{friendlyTestMessage(row.last_test_message)}}</small></div></template></el-table-column><el-table-column label="回答长度" width="130"><template #default="{row}">最多 {{row.max_tokens}} Token</template></el-table-column><el-table-column label="操作" width="300" fixed="right"><template #default="{row}"><el-button size="small" @click="openEditor(row)">编辑</el-button><el-button size="small" :loading="busy.has(row.id)" @click="test(row.id)">测试连接</el-button><el-button size="small" type="primary" :disabled="row.is_default||row.last_test_status!=='SUCCESS'" :loading="busy.has(row.id)" @click="activate(row.id)">设为当前</el-button><el-popconfirm title="确认删除该模型配置？" @confirm="remove(row.id)"><template #reference><el-button size="small" type="danger">删除</el-button></template></el-popconfirm></template></el-table-column>
    </el-table></div></section>
    <el-dialog v-model="editorVisible" :title="form.id?'编辑模型配置':'添加模型配置'" width="min(700px,94vw)">
      <el-form label-position="top" class="config-grid">
        <el-form-item label="配置名称"><el-input v-model="form.name" placeholder="例如：日常分析模型"/><small>用于区分多个模型配置，仅自己可见。</small></el-form-item>
        <el-form-item label="模型服务商"><el-select v-model="form.provider_code" @change="providerChanged"><el-option v-for="item in providers" :key="item.code" :label="item.display_name" :value="item.code"/></el-select><small>支持 OpenAI、DeepSeek、Gemini、豆包、通义和 Kimi。</small></el-form-item>
        <el-form-item label="模型名称"><el-input v-model="form.model" :placeholder="modelSuggestion"/><small>填写服务商控制台展示的模型标识。</small></el-form-item>
        <el-form-item label="API Key（访问密钥）"><el-input v-model="form.api_key" type="password" show-password :placeholder="form.id?'留空表示保留原密钥':'粘贴服务商提供的 API Key'" autocomplete="new-password"/><small>密钥不会在列表中明文显示。</small></el-form-item>
        <el-form-item class="full"><el-switch v-model="form.enabled" active-text="启用该配置" inactive-text="暂不启用"/></el-form-item>
        <el-form-item class="full advanced"><el-collapse><el-collapse-item title="高级参数（不确定时保持默认即可）" name="advanced"><div class="config-grid inner">
          <el-form-item class="full" label="服务地址 Base URL"><el-input v-model="form.base_url"/><small>模型接口地址，选择服务商后会自动填写，通常不需要修改。</small></el-form-item>
          <el-form-item label="回答随机性 Temperature"><el-slider v-model="form.temperature" :min="0" :max="2" :step="0.1" show-input/><small>越低越稳定。量化分析推荐 0.2，不建议新手调高。</small></el-form-item>
          <el-form-item label="最长等待时间"><el-input-number v-model="form.timeout_seconds" :min="5" :max="300"/><small>超过该秒数仍未响应就停止等待，推荐 60 秒。</small></el-form-item>
          <el-form-item label="单次回答最大长度"><el-input-number v-model="form.max_tokens" :min="256" :max="131072" :step="256"/><small>只限制模型输出的报告长度。4096 适合普通报告；数值越大，费用和等待时间通常越高。</small></el-form-item>
          <el-form-item label="模型上下文容量"><el-input-number v-model="form.context_window_tokens" :min="8192" :max="2000000" :step="8192"/><small>模型一次最多可读取的内容容量，不代表每次都会消耗这么多。请按服务商文档填写。</small></el-form-item>
        </div></el-collapse-item></el-collapse></el-form-item>
      </el-form>
      <template #footer><el-button @click="editorVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存配置</el-button></template>
    </el-dialog>
    <section class="data-table-card usage-table"><div class="toolbar"><strong>最近 30 天调用明细</strong><span class="muted">供应商未返回 Token 时会明确标记为“系统估算”</span></div><div class="table-scroll-x"><el-table :data="usageRecords" empty-text="当前账号暂无模型调用记录">
      <el-table-column label="时间" width="170"><template #default="{row}">{{formatTime(row.created_at)}}</template></el-table-column><el-table-column label="用途" width="150"><template #default="{row}">{{requestTypeLabel(row.request_type)}}</template></el-table-column><el-table-column prop="model" label="模型" min-width="170"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='SUCCESS'?'success':'danger'">{{row.status==='SUCCESS'?'成功':'失败'}}</el-tag></template></el-table-column><el-table-column label="输入 / 输出" width="150"><template #default="{row}">{{compactNumber(row.prompt_tokens)}} / {{compactNumber(row.completion_tokens)}}</template></el-table-column><el-table-column label="用量口径" width="110"><template #default="{row}">{{row.token_source==='PROVIDER'?'供应商返回':row.token_source==='LOCAL'?'本地引擎':'系统估算'}}</template></el-table-column><el-table-column label="响应时间" width="110"><template #default="{row}">{{row.latency_ms}} ms</template></el-table-column><el-table-column label="报告" width="90"><template #default="{row}"><el-button v-if="row.report_id" link type="primary" @click="$router.push(`/agent/reports/${row.report_id}`)">查看</el-button><span v-else>--</span></template></el-table-column><el-table-column prop="error_message" label="失败原因" min-width="220" show-overflow-tooltip/>
    </el-table></div></section>
  </PageContainer>
</template>
<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import PageContainer from'@/components/common/PageContainer.vue';import DataCard from'@/components/common/DataCard.vue';import{modelApi}from'@/api/model';import{compactNumber}from'@/utils/format';import{formatTime}from'@/utils/time';import type{ModelConfig,ModelProvider,ModelUsage,ModelUsageRecord}from'@/types/model'
const providers=ref<ModelProvider[]>([]),configs=ref<ModelConfig[]>([]),usageRecords=ref<ModelUsageRecord[]>([]),usage=ref<ModelUsage>({requests:0,success_requests:0,failed_requests:0,total_tokens:0,prompt_tokens:0,completion_tokens:0,average_latency_ms:0,p95_latency_ms:0,success_rate:0}),loading=ref(false),saving=ref(false),editorVisible=ref(false),busy=ref(new Set<number>()),form=reactive({id:0,name:'',provider_code:'deepseek',base_url:'',model:'',api_key:'',temperature:0.2,timeout_seconds:60,max_tokens:4096,context_window_tokens:1000000,enabled:true})
const modelDefaults:Record<string,string>={openai:'gpt-4.1-mini',deepseek:'deepseek-v4-pro',gemini:'gemini-2.5-flash',doubao:'doubao-seed-1-6',qwen:'qwen-plus',kimi:'kimi-k2'}
const modelSuggestion=computed(()=>`例如：${modelDefaults[form.provider_code]||'服务商模型名称'}`)
const load=async()=>{loading.value=true;try{const[p,c,u,r]=await Promise.all([modelApi.providers(),modelApi.configs(),modelApi.usage(),modelApi.usageRecords()]);providers.value=p;configs.value=c;usage.value=u;usageRecords.value=r.items||[]}finally{loading.value=false}}
const providerName=(code:string)=>providers.value.find(v=>v.code===code)?.display_name||code;const testTag=(v:string)=>v==='SUCCESS'?'success':v==='FAILED'?'danger':'info';const testStatus=(v:string)=>v==='SUCCESS'?'连接成功':v==='FAILED'?'连接失败':'尚未测试'
const friendlyTestMessage=(message:string)=>message.includes('DeadlineExceeded')||message.includes('context deadline')?'连接等待超时，请检查网络后重试':message.includes('HTTP 401')?'API Key 无效或已失效':message.includes('HTTP 402')?'账户余额不足':message.includes('HTTP 429')?'请求过于频繁，请稍后重试':message.includes('HTTP 400')?'模型名称或请求参数不受服务商支持':message
const providerChanged=()=>{const p=providers.value.find(v=>v.code===form.provider_code);if(p)form.base_url=p.default_base_url;form.model=modelDefaults[form.provider_code]||'';form.context_window_tokens=form.provider_code==='deepseek'?1000000:128000}
const openEditor=(row?:ModelConfig)=>{Object.assign(form,row?{id:row.id,name:row.name,provider_code:row.provider_code,base_url:row.base_url,model:row.model,api_key:'',temperature:row.temperature,timeout_seconds:row.timeout_seconds,max_tokens:row.max_tokens,context_window_tokens:row.context_window_tokens||128000,enabled:row.enabled}:{id:0,name:'日常量化分析',provider_code:'deepseek',base_url:providers.value.find(v=>v.code==='deepseek')?.default_base_url||'',model:'deepseek-v4-pro',api_key:'',temperature:.2,timeout_seconds:60,max_tokens:4096,context_window_tokens:1000000,enabled:true});editorVisible.value=true}
const requestTypeLabel=(value:string)=>({ANALYZE_STOCK:'个股分析',ASK_WITH_RAG:'知识问答',REVIEW_BACKTEST:'回测复盘',REVIEW_PAPER_ACCOUNT:'账户复盘',CONNECTION_TEST:'连接测试'}[value]||value||'智能分析')
const save=async()=>{if(!form.name.trim()||!form.model.trim())return ElMessage.warning('请填写配置名称和模型名称');saving.value=true;try{await modelApi.save({...form});ElMessage.success('模型配置保存成功，请继续执行连接测试');editorVisible.value=false;await load()}finally{saving.value=false}}
const withBusy=async(id:number,fn:()=>Promise<unknown>)=>{busy.value=new Set(busy.value).add(id);try{await fn()}finally{const n=new Set(busy.value);n.delete(id);busy.value=n}}
const test=async(id:number)=>withBusy(id,async()=>{const r=await modelApi.test(id);r.success?ElMessage.success(`连接成功，响应耗时 ${r.latency_ms} 毫秒`):ElMessage.error(`连接失败：${r.message}`);await load()});const activate=async(id:number)=>withBusy(id,async()=>{await modelApi.activate(id);ElMessage.success('设置成功，智能体将优先使用该模型');await load()});const remove=async(id:number)=>{await modelApi.remove(id);ElMessage.success('模型配置删除成功');await load()};onMounted(load)
</script>
<style scoped>.notice{margin-bottom:14px}.usage-metrics{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:16px}.usage-metrics>*{flex:1 1 180px;min-width:170px;min-height:112px}.usage-table{margin-top:16px}.model-table{min-width:1360px}.test-result{display:flex;flex-direction:column;gap:5px}.test-result small{color:var(--qs-muted);line-height:1.35;white-space:normal}.config-grid{display:flex;flex-direction:column;gap:0}.config-grid small{display:block;color:var(--qs-muted);margin-top:6px;line-height:1.5}.config-grid.inner{flex-direction:row;flex-wrap:wrap;gap:0 16px;padding-top:8px}.config-grid.inner>.el-form-item{flex:1 1 280px;min-width:0}.config-grid.inner>.full{flex-basis:100%}.advanced :deep(.el-collapse){width:100%;border-bottom:0}@media(max-width:640px){.usage-metrics>*{flex-basis:calc(50% - 6px);min-width:140px}.config-grid.inner{flex-direction:column}.config-grid.inner>.el-form-item{width:100%;flex-basis:auto}}@media(max-width:390px){.usage-metrics>*{flex-basis:100%}}</style>
